#!/usr/bin/env node
/**
 * Bundle the first-party frontend into a single ES module.
 *
 * The 186 modules under static/js/ are served individually in development so
 * the edit->refresh loop keeps working with no build step. This produces the
 * artifact shipped in the wheel and the Docker image, where a cold load is
 * otherwise 195 requests across ~6 dependency waves.
 *
 * Output is gitignored (static/dist/) and generated by CI at release time,
 * NOT committed — unlike the vendor bundles, this changes on every frontend
 * edit and would bloat the history. The server prefers it when present, so a
 * checkout without it simply serves per-file (see _bundle_path in server.py).
 *
 *   node build-app.mjs [--out DIR]
 */
import esbuild from 'esbuild';
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { parse as parseYaml } from 'yaml';

const PKG = path.resolve(import.meta.dirname, '../../src/painapple_code');
const JS_DIR = path.join(PKG, 'static/js');
const outArg = process.argv.indexOf('--out');
const OUT_DIR = outArg > -1 ? path.resolve(process.argv[outArg + 1]) : path.join(PKG, 'static/dist');
const OUT_FILE = path.join(OUT_DIR, 'app.bundle.js');

// strings.js does not exist on disk — the server generates it from
// data/strings.yaml and 100 modules import it. Resolve those imports to a
// synthetic module holding the same payload the server would have served.
const stringsPlugin = {
  name: 'painapple-strings',
  setup(build) {
    const NS = 'painapple-strings';
    build.onResolve({ filter: /(^|\/)strings\.js$/ }, (args) =>
      args.path.startsWith('.') ? { path: 'strings', namespace: NS } : undefined
    );
    build.onLoad({ filter: /.*/, namespace: NS }, () => {
      const yamlPath = path.join(PKG, 'data/strings.yaml');
      const data = parseYaml(fs.readFileSync(yamlPath, 'utf8'));
      return {
        contents: `export default ${JSON.stringify(data)};`,
        loader: 'js',
        watchFiles: [yamlPath],
      };
    });
  },
};

fs.rmSync(OUT_DIR, { recursive: true, force: true });
fs.mkdirSync(OUT_DIR, { recursive: true });

const result = await esbuild.build({
  entryPoints: [path.join(JS_DIR, 'app.js')],
  outfile: OUT_FILE,
  bundle: true,
  format: 'esm',
  target: 'es2022',
  minify: true,
  // Class/function names survive minification: stack traces from user bug
  // reports stay readable, and nothing has to care that `app.constructor.name`
  // would otherwise be a two-letter mangle.
  keepNames: true,
  // Off by default: the wheel and image ship the original 186 modules anyway,
  // and PAINAPPLE_NO_BUNDLE=1 serves them — real sources beat a 5.8 MB map.
  sourcemap: process.argv.includes('--sourcemap') ? 'linked' : false,
  // The vendor bundles are prebuilt and loaded lazily by absolute URL
  // (codemirror ~1 MB, xterm ~283 KB). They must stay separate requests.
  external: ['/static/*'],
  plugins: [stringsPlugin],
  metafile: true,
  logLevel: 'warning',
});

const bytes = fs.readFileSync(OUT_FILE);
const gz = zlib.gzipSync(bytes, { level: 6 }).length;
const modules = Object.keys(result.metafile.inputs).length;
console.log(
  `built ${path.relative(process.cwd(), OUT_FILE)}: ` +
    `${modules} modules -> ${(bytes.length / 1048576).toFixed(2)} MB ` +
    `(${(gz / 1024).toFixed(0)} KB gzipped)`
);

// A truncated or half-written bundle would be served as the whole frontend.
if (modules < 150) {
  console.error(`refusing to ship a bundle with only ${modules} modules`);
  process.exit(1);
}
